insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-foam-roll-quads-hip-flexors', 'Foam Roll – Quads & Hip Flexors', 'mef-custom-foam-roll-quads-hip-flexors', 'Self-myofascial release for the front of the thigh and hip.', ARRAY['Lie face-down and prop your forearms on the floor, foam roller placed just above the kneecaps.','Roll slowly from just above the knee up to the hip crease, pausing 20-30 seconds on any tender spot instead of rolling fast over it.','Keep your core braced and hips level. Don''t let your low back sag toward the floor.']::text[], ARRAY['Common mistake: rolling directly over the kneecap or straight onto the front of the hip bone. Stay on muscle, not joint.']::text[], 'quads', ARRAY['hip_flexors']::text[], 'foam roller', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-foam-roll-quads-hip-flexors', ARRAY['foam roller']::text[], 'beginner', ARRAY['Lie face-down and prop your forearms on the floor, foam roller placed just above the kneecaps.','Roll slowly from just above the knee up to the hip crease, pausing 20-30 seconds on any tender spot instead of rolling fast over it.','Keep your core braced and hips level. Don''t let your low back sag toward the floor.','Breathe slow and steady through any tender spot; tension easing is the goal, not gritting through pain.','Common mistake: rolling directly over the kneecap or straight onto the front of the hip bone. Stay on muscle, not joint.','60-90 seconds per leg.']::text[], ARRAY['release']::text[], ARRAY['quads','hip flexors']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-foam-roll-tfl-it-band', 'Foam Roll – TFL / IT Band', 'mef-custom-foam-roll-tfl-it-band', 'Self-myofascial release for the outer hip and IT band.', ARRAY['Lie on your side with the roller just below your hip bone, top leg bent and foot planted in front for balance.','Roll slowly from the hip down toward mid-thigh, staying on the outer thigh line.','Keep your supporting arm strong and your hips stacked. Don''t let your top hip roll forward or back.']::text[], ARRAY['Common mistake: parking directly on the hip bone itself. Shift slightly down onto the muscle below it.']::text[], 'hip_flexors', '{}'::text[], 'foam roller', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-foam-roll-tfl-it-band', ARRAY['foam roller']::text[], 'beginner', ARRAY['Lie on your side with the roller just below your hip bone, top leg bent and foot planted in front for balance.','Roll slowly from the hip down toward mid-thigh, staying on the outer thigh line.','Keep your supporting arm strong and your hips stacked. Don''t let your top hip roll forward or back.','Breathe steadily; ease off the pressure by taking more weight through your top foot if a spot is sharp rather than dull.','Common mistake: parking directly on the hip bone itself. Shift slightly down onto the muscle below it.','45-60 seconds per side.']::text[], ARRAY['release']::text[], ARRAY['TFL']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-foam-roll-glutes', 'Foam Roll – Glutes', 'mef-custom-foam-roll-glutes', 'Self-myofascial release for the glutes.', ARRAY['Sit on the roller with one ankle crossed over the opposite knee, leaning slightly toward the crossed-leg side.','Roll slowly from the top of the glute down toward the top of the thigh.','Support some of your weight through your hands behind you so you can control the pressure.']::text[], ARRAY['Common mistake: rushing over the whole area instead of pausing on the spots that actually feel tight.']::text[], 'glutes', '{}'::text[], 'foam roller', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-foam-roll-glutes', ARRAY['foam roller']::text[], 'beginner', ARRAY['Sit on the roller with one ankle crossed over the opposite knee, leaning slightly toward the crossed-leg side.','Roll slowly from the top of the glute down toward the top of the thigh.','Support some of your weight through your hands behind you so you can control the pressure.','Breathe out as you settle into a tender spot rather than tensing against it.','Common mistake: rushing over the whole area instead of pausing on the spots that actually feel tight.','60 seconds per side.']::text[], ARRAY['release']::text[], ARRAY['glutes']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-foam-roll-hamstrings', 'Foam Roll – Hamstrings', 'mef-custom-foam-roll-hamstrings', 'Self-myofascial release for the back of the thigh.', ARRAY['Sit with the roller under your thighs, hands planted behind you for support, knees soft.','Roll from just below the glutes down to just above the knee.','Keep your shoulders back and chest open rather than rounding forward over the roller.']::text[], ARRAY['Common mistake: rolling straight across the back of the knee. Stop just above the joint.']::text[], 'hamstrings', '{}'::text[], 'foam roller', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-foam-roll-hamstrings', ARRAY['foam roller']::text[], 'beginner', ARRAY['Sit with the roller under your thighs, hands planted behind you for support, knees soft.','Roll from just below the glutes down to just above the knee.','Keep your shoulders back and chest open rather than rounding forward over the roller.','Breathe slowly; let your body weight sink into any tight band instead of holding it away.','Common mistake: rolling straight across the back of the knee. Stop just above the joint.','60-90 seconds total.']::text[], ARRAY['release']::text[], ARRAY['hamstrings']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-foam-roll-lats', 'Foam Roll – Lats', 'mef-custom-foam-roll-lats', 'Self-myofascial release for the lats along the side of the ribcage.', ARRAY['Lie on your side, roller angled under your armpit, arm reaching overhead.','Roll slowly from your armpit down toward the bottom of your ribcage.','Keep your bottom knee bent and use it to control how much pressure you load through the roller.']::text[], ARRAY['Common mistake: rolling directly over the shoulder joint. Stay on the muscle along the side of the ribs.']::text[], 'lats', '{}'::text[], 'foam roller', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-foam-roll-lats', ARRAY['foam roller']::text[], 'beginner', ARRAY['Lie on your side, roller angled under your armpit, arm reaching overhead.','Roll slowly from your armpit down toward the bottom of your ribcage.','Keep your bottom knee bent and use it to control how much pressure you load through the roller.','Breathe out as you find a tender spot and let the tissue soften under it rather than bracing.','Common mistake: rolling directly over the shoulder joint. Stay on the muscle along the side of the ribs.','45-60 seconds per side.']::text[], ARRAY['release']::text[], ARRAY['lats']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-foam-roll-thoracic-spine', 'Foam Roll – Thoracic Spine', 'mef-custom-foam-roll-thoracic-spine', 'Self-myofascial release and gentle extension mobility for the upper/mid back.', ARRAY['Lie on your back with the roller placed horizontally under your shoulder blades, knees bent, hands cradling your head.','Lift your hips slightly and roll a few inches up and down the mid-back, pausing at any stiff segment.','Let your head and ribcage drape back over the roller at each pause to open the upper back into extension.']::text[], ARRAY['Common mistake: rolling down into the low back. Stay above the bottom of the ribcage, the lumbar spine doesn''t roll the same way.']::text[], 'back', ARRAY['upper_back']::text[], 'foam roller', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-foam-roll-thoracic-spine', ARRAY['foam roller']::text[], 'beginner', ARRAY['Lie on your back with the roller placed horizontally under your shoulder blades, knees bent, hands cradling your head.','Lift your hips slightly and roll a few inches up and down the mid-back, pausing at any stiff segment.','Let your head and ribcage drape back over the roller at each pause to open the upper back into extension.','Breathe fully into your chest at each pause rather than holding your breath.','Common mistake: rolling down into the low back. Stay above the bottom of the ribcage, the lumbar spine doesn''t roll the same way.','6-8 slow passes, or 45-60 seconds total.']::text[], ARRAY['release']::text[], ARRAY['upper back']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-ball-release-pecs', 'Ball Release – Pecs (Chest)', 'mef-custom-ball-release-pecs', 'Self-myofascial release for the chest using a wall and a massage ball.', ARRAY['Stand facing a wall and place a massage ball just below your collarbone, toward the outer chest.','Lean in until you feel firm pressure, then make small slow circles or lift your arm overhead and lower it a few times.','Keep your shoulder relaxed down away from your ear rather than shrugged up.']::text[], ARRAY['Common mistake: working directly over the collarbone or armpit. Stay on the fleshy muscle of the chest.']::text[], 'chest', '{}'::text[], 'ball', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-ball-release-pecs', ARRAY['ball']::text[], 'beginner', ARRAY['Stand facing a wall and place a massage ball just below your collarbone, toward the outer chest.','Lean in until you feel firm pressure, then make small slow circles or lift your arm overhead and lower it a few times.','Keep your shoulder relaxed down away from your ear rather than shrugged up.','Breathe steadily; back off pressure if you feel sharp pain, numbness, or tingling into the arm.','Common mistake: working directly over the collarbone or armpit. Stay on the fleshy muscle of the chest.','45-60 seconds per side.']::text[], ARRAY['release']::text[], ARRAY['pecs']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-suboccipital-release-supine-double-ball', 'Suboccipital Release – Supine (Double Ball)', 'mef-custom-suboccipital-release-supine-double-ball', 'Gentle self-release for the base of the skull using two small balls or a peanut-shaped double ball.', ARRAY['Lie on your back with two small balls (or a peanut-shaped double ball) placed at the base of your skull, one on each side of the spine.','Let your head rest into the balls and gently nod ''yes'' in small slow movements.','Keep your chin gently tucked rather than tipping your head back.']::text[], ARRAY['Common mistake: pressing directly on the spine itself. The balls should sit in the muscle just to either side of it.']::text[], 'neck', '{}'::text[], 'ball', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-suboccipital-release-supine-double-ball', ARRAY['ball']::text[], 'beginner', ARRAY['Lie on your back with two small balls (or a peanut-shaped double ball) placed at the base of your skull, one on each side of the spine.','Let your head rest into the balls and gently nod ‘yes’ in small slow movements.','Keep your chin gently tucked rather than tipping your head back.','Breathe slowly and let your neck soften with each small nod.','Common mistake: pressing directly on the spine itself. The balls should sit in the muscle just to either side of it.','60-90 seconds.']::text[], ARRAY['release']::text[], ARRAY['suboccipitals']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-ball-release-upper-traps', 'Ball Release – Upper Traps', 'mef-custom-ball-release-upper-traps', 'Self-myofascial release for the upper traps using a wall and a massage ball.', ARRAY['Stand with your back to a wall and place a ball between the wall and the muscle just above your shoulder blade, at the base of your neck.','Lean back to load the ball, then slowly tip your ear toward the opposite shoulder and back.','Keep your jaw relaxed and shoulders down rather than hunching them up toward your ears.']::text[], ARRAY['Common mistake: working right at the top of the shoulder joint instead of the muscle between neck and shoulder.']::text[], 'upper_traps', '{}'::text[], 'ball', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-ball-release-upper-traps', ARRAY['ball']::text[], 'beginner', ARRAY['Stand with your back to a wall and place a ball between the wall and the muscle just above your shoulder blade, at the base of your neck.','Lean back to load the ball, then slowly tip your ear toward the opposite shoulder and back.','Keep your jaw relaxed and shoulders down rather than hunching them up toward your ears.','Breathe out as you tip away from the ball to deepen the release.','Common mistake: working right at the top of the shoulder joint instead of the muscle between neck and shoulder.','45-60 seconds per side.']::text[], ARRAY['release']::text[], ARRAY['upper traps']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-tfl-stretch-standing-cross-leg', 'TFL / IT Band Stretch – Standing Cross-Leg', 'mef-custom-tfl-stretch-standing-cross-leg', 'Standing stretch for the outer hip (TFL/IT band).', ARRAY['Stand tall, cross the leg you''re stretching behind the other, feet a few inches apart.','Reach the same-side arm overhead and lean your torso away from the crossed leg.','Keep your hips facing forward. The lean should come from your side body, not a forward bend.']::text[], ARRAY['Common mistake: rounding forward at the waist instead of side-bending. Keep your chest open.']::text[], 'hip_flexors', '{}'::text[], 'bodyweight', 'stretching', 'beginner', ARRAY['stretching']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-tfl-stretch-standing-cross-leg', ARRAY['bodyweight']::text[], 'beginner', ARRAY['Stand tall, cross the leg you''re stretching behind the other, feet a few inches apart.','Reach the same-side arm overhead and lean your torso away from the crossed leg.','Keep your hips facing forward. The lean should come from your side body, not a forward bend.','Breathe out as you lean into a gentle stretch along the outer hip and thigh.','Common mistake: rounding forward at the waist instead of side-bending. Keep your chest open.','Hold 20-30 seconds per side, repeat twice.']::text[], ARRAY['stretch']::text[], ARRAY['TFL']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-it-band-stretch-side-lying-strap', 'IT Band Stretch – Side-Lying with Strap or Towel', 'mef-custom-it-band-stretch-side-lying-strap', 'Supine strap-assisted stretch for the outer hip (TFL/IT band).', ARRAY['Lie on your back, loop a towel or strap around the foot of the leg you''re stretching.','Keeping that knee straight, guide the leg across your body toward the floor on the opposite side.','Keep both shoulder blades flat on the floor rather than letting your torso twist along with the leg.']::text[], ARRAY['Common mistake: forcing the leg all the way to the floor. Stop where you feel a stretch, not strain.']::text[], 'hip_flexors', '{}'::text[], 'towel', 'stretching', 'beginner', ARRAY['stretching']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-it-band-stretch-side-lying-strap', ARRAY['towel']::text[], 'beginner', ARRAY['Lie on your back, loop a towel or strap around the foot of the leg you''re stretching.','Keeping that knee straight, guide the leg across your body toward the floor on the opposite side.','Keep both shoulder blades flat on the floor rather than letting your torso twist along with the leg.','Breathe slowly as you feel a gentle pull along the outer hip and thigh.','Common mistake: forcing the leg all the way to the floor. Stop where you feel a stretch, not strain.','Hold 20-30 seconds per side.']::text[], ARRAY['stretch']::text[], ARRAY['TFL']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-doorway-pec-stretch-low', 'Doorway Pec Stretch – Low Angle (Lower Fibers)', 'mef-custom-doorway-pec-stretch-low', 'Doorway stretch targeting the lower chest fibers.', ARRAY['Stand in a doorway, forearm on the frame with your elbow just below shoulder height.','Step through the doorway with the same-side foot until you feel a stretch across the lower chest.','Keep your ribs down and core braced rather than arching your low back to reach further.']::text[], ARRAY['Common mistake: letting the shoulder hike up toward the ear. Keep it pulled gently down.']::text[], 'chest', '{}'::text[], 'doorway', 'stretching', 'beginner', ARRAY['stretching']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-doorway-pec-stretch-low', ARRAY['doorway']::text[], 'beginner', ARRAY['Stand in a doorway, forearm on the frame with your elbow just below shoulder height.','Step through the doorway with the same-side foot until you feel a stretch across the lower chest.','Keep your ribs down and core braced rather than arching your low back to reach further.','Breathe out as you settle into the stretch.','Common mistake: letting the shoulder hike up toward the ear. Keep it pulled gently down.','Hold 20-30 seconds per side, repeat twice.']::text[], ARRAY['stretch']::text[], ARRAY['pecs']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-doorway-pec-stretch-high', 'Doorway Pec Stretch – High Angle (Upper/Clavicular Fibers)', 'mef-custom-doorway-pec-stretch-high', 'Doorway stretch targeting the upper, clavicular chest fibers.', ARRAY['Stand in a doorway, forearm on the frame with your elbow just above shoulder height.','Step through with the same-side foot until you feel a stretch across the upper chest, near the collarbone.','Keep your chin level and chest open rather than jutting your head forward.']::text[], ARRAY['Common mistake: pushing through pinching pain in the front of the shoulder. Back the angle down if you feel that.']::text[], 'chest', ARRAY['upper_chest']::text[], 'doorway', 'stretching', 'beginner', ARRAY['stretching']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-doorway-pec-stretch-high', ARRAY['doorway']::text[], 'beginner', ARRAY['Stand in a doorway, forearm on the frame with your elbow just above shoulder height.','Step through with the same-side foot until you feel a stretch across the upper chest, near the collarbone.','Keep your chin level and chest open rather than jutting your head forward.','Breathe out as you ease deeper into the stretch.','Common mistake: pushing through pinching pain in the front of the shoulder. Back the angle down if you feel that.','Hold 20-30 seconds per side, repeat twice.']::text[], ARRAY['stretch']::text[], ARRAY['pecs']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-kneeling-lat-stretch', 'Kneeling Lat Stretch', 'mef-custom-kneeling-lat-stretch', 'Kneeling stretch for the lats using a bench or low chair.', ARRAY['Kneel in front of a bench or low chair, reach both arms forward and rest them on top.','Sit your hips back toward your heels and let your chest melt toward the floor.','Keep your arms straight and reach through your fingertips rather than collapsing at the elbows.']::text[], ARRAY['Common mistake: arching hard through the low back to get lower. Let the stretch come from the shoulders and ribs, not the spine.']::text[], 'lats', '{}'::text[], 'bodyweight', 'stretching', 'beginner', ARRAY['stretching']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-kneeling-lat-stretch', ARRAY['bodyweight']::text[], 'beginner', ARRAY['Kneel in front of a bench or low chair, reach both arms forward and rest them on top.','Sit your hips back toward your heels and let your chest melt toward the floor.','Keep your arms straight and reach through your fingertips rather than collapsing at the elbows.','Breathe out as your ribcage lowers, feeling the stretch down the side of your back.','Common mistake: arching hard through the low back to get lower. Let the stretch come from the shoulders and ribs, not the spine.','Hold 30 seconds, repeat 2-3 times.']::text[], ARRAY['stretch']::text[], ARRAY['lats']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-levator-scapulae-stretch-seated', 'Levator Scapulae Stretch – Seated (Chin-to-Armpit)', 'mef-custom-levator-scapulae-stretch-seated', 'Seated stretch for the levator scapulae, chin turned toward the armpit.', ARRAY['Sit tall, anchor one hand under the seat of your chair on the side you''re stretching.','Turn your chin toward your opposite armpit, then gently tip your head forward and down.','Use your free hand to add very light, gentle pressure on the back of the head. Never pull hard.']::text[], ARRAY['Common mistake: forcing the stretch with the hand. Let your own head weight do most of the work.']::text[], 'neck', '{}'::text[], 'bodyweight', 'stretching', 'beginner', ARRAY['stretching']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-levator-scapulae-stretch-seated', ARRAY['bodyweight']::text[], 'beginner', ARRAY['Sit tall, anchor one hand under the seat of your chair on the side you''re stretching.','Turn your chin toward your opposite armpit, then gently tip your head forward and down.','Use your free hand to add very light, gentle pressure on the back of the head. Never pull hard.','Breathe slowly; the stretch should feel like a gentle pull along the side/back of the neck, not a sharp one.','Common mistake: forcing the stretch with the hand. Let your own head weight do most of the work.','Hold 20-30 seconds per side.']::text[], ARRAY['stretch']::text[], ARRAY['levator scapulae']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-levator-scapulae-stretch-standing-wall', 'Levator Scapulae Stretch – Standing, Wall-Assisted', 'mef-custom-levator-scapulae-stretch-standing-wall', 'Standing stretch for the levator scapulae with the shoulder anchored against a wall.', ARRAY['Stand with one shoulder near a wall, that arm reaching back to hold the wall at hip height to anchor the shoulder down.','Turn your chin toward the opposite armpit and gently tip your head forward and down.','Keep the anchored shoulder pulled gently down and back rather than hiking up.']::text[], ARRAY['Common mistake: letting the anchored shoulder creep up toward the ear, which cancels out the stretch.']::text[], 'neck', '{}'::text[], 'wall', 'stretching', 'beginner', ARRAY['stretching']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-levator-scapulae-stretch-standing-wall', ARRAY['wall']::text[], 'beginner', ARRAY['Stand with one shoulder near a wall, that arm reaching back to hold the wall at hip height to anchor the shoulder down.','Turn your chin toward the opposite armpit and gently tip your head forward and down.','Keep the anchored shoulder pulled gently down and back rather than hiking up.','Breathe out as you settle into the stretch along the side of the neck.','Common mistake: letting the anchored shoulder creep up toward the ear, which cancels out the stretch.','Hold 20-30 seconds per side.']::text[], ARRAY['stretch']::text[], ARRAY['levator scapulae']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-levator-scapulae-self-release-ball', 'Levator Scapulae Self-Release (Ball)', 'mef-custom-levator-scapulae-self-release-ball', 'Self-release for the levator scapulae at the neck-shoulder junction using a wall and a massage ball.', ARRAY['Stand with your back to a wall and place a ball at the base of your neck, just to one side where the neck meets the top of the shoulder blade.','Lean back gently to load the ball, then slowly turn your chin a few inches side to side.','Keep your jaw and shoulders relaxed rather than bracing against the pressure.']::text[], ARRAY['Common mistake: pressing directly on the side of the neck itself. Stay on the muscle at the neck-shoulder junction.']::text[], 'neck', '{}'::text[], 'ball', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-levator-scapulae-self-release-ball', ARRAY['ball']::text[], 'beginner', ARRAY['Stand with your back to a wall and place a ball at the base of your neck, just to one side where the neck meets the top of the shoulder blade.','Lean back gently to load the ball, then slowly turn your chin a few inches side to side.','Keep your jaw and shoulders relaxed rather than bracing against the pressure.','Breathe slowly and steadily through the release.','Common mistake: pressing directly on the side of the neck itself. Stay on the muscle at the neck-shoulder junction.','45-60 seconds per side.']::text[], ARRAY['release']::text[], ARRAY['levator scapulae']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-suboccipital-release-seated-wall', 'Suboccipital Release – Seated, Wall-Assisted', 'mef-custom-suboccipital-release-seated-wall', 'Seated self-release for the base of the skull against a wall.', ARRAY['Sit with your back against a wall, place a ball (or two small balls) at the base of your skull where your neck meets your head.','Gently press your head back into the ball and slowly nod your chin down and up in a small range.','Keep your chin very slightly tucked throughout rather than letting your head tip back.']::text[], ARRAY['Common mistake: pressing hard and holding still. Small slow movement works better here than static pressure.']::text[], 'neck', '{}'::text[], 'ball', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-suboccipital-release-seated-wall', ARRAY['ball']::text[], 'beginner', ARRAY['Sit with your back against a wall, place a ball (or two small balls) at the base of your skull where your neck meets your head.','Gently press your head back into the ball and slowly nod your chin down and up in a small range.','Keep your chin very slightly tucked throughout rather than letting your head tip back.','Breathe slowly; this is a gentle release, not a deep-pressure one. Ease off if it feels sharp.','Common mistake: pressing hard and holding still. Small slow movement works better here than static pressure.','60 seconds.']::text[], ARRAY['release']::text[], ARRAY['suboccipitals']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-suboccipital-active-stretch-chin-glide', 'Suboccipital Release – Active Chin Glide', 'mef-custom-suboccipital-active-stretch-chin-glide', 'Active mobility stretch for the base of the skull. A gentle chin glide, not a strength hold.', ARRAY['Sit or stand tall, eyes level.','Without tipping your head down, glide your chin straight back as if making a double chin, then let it glide gently forward again.','Keep the movement small and slow. This is a glide, not a nod.']::text[], ARRAY['Common mistake: dropping the chin down toward the chest instead of gliding it straight back.']::text[], 'neck', '{}'::text[], 'bodyweight', 'stretching', 'beginner', ARRAY['stretching']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-suboccipital-active-stretch-chin-glide', ARRAY['bodyweight']::text[], 'beginner', ARRAY['Sit or stand tall, eyes level.','Without tipping your head down, glide your chin straight back as if making a double chin, then let it glide gently forward again.','Keep the movement small and slow. This is a glide, not a nod.','Breathe out as you glide back, feeling a gentle stretch at the base of the skull.','Common mistake: dropping the chin down toward the chest instead of gliding it straight back.','10 slow reps, hold the back position 2 seconds each time.']::text[], ARRAY['stretch']::text[], ARRAY['suboccipitals']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-chin-tuck-supine', 'Chin Tuck – Supine', 'mef-custom-chin-tuck-supine', 'Deep neck flexor strengthening, lying down. The entry-level chin tuck.', ARRAY['Lie on your back, knees bent, a small flat pillow or towel under your head if needed for neutral alignment.','Without lifting your head, gently nod your chin down and glide the back of your head slightly up and away, like making a double chin.','Keep your jaw relaxed and neck long. This is a small, subtle motion, not a big head lift.']::text[], ARRAY['Common mistake: using the big muscles at the front of the neck to yank the chin down. The motion should feel deep and subtle, not strained.']::text[], 'neck', '{}'::text[], 'bodyweight', 'face-neck', 'beginner', ARRAY['rehabilitation']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-chin-tuck-supine', ARRAY['bodyweight']::text[], 'beginner', ARRAY['Lie on your back, knees bent, a small flat pillow or towel under your head if needed for neutral alignment.','Without lifting your head, gently nod your chin down and glide the back of your head slightly up and away, like making a double chin.','Keep your jaw relaxed and neck long. This is a small, subtle motion, not a big head lift.','Breathe normally throughout; don''t hold your breath to brace.','Common mistake: using the big muscles at the front of the neck to yank the chin down. The motion should feel deep and subtle, not strained.','Hold each rep 5 seconds, 8-10 reps.']::text[], ARRAY['stability']::text[], '{}'::text[], ARRAY['deep neck flexors']::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-chin-tuck-standing-wall', 'Chin Tuck – Standing (Wall-Assisted)', 'mef-custom-chin-tuck-standing-wall', 'Deep neck flexor strengthening, standing against a wall.', ARRAY['Stand with your back, shoulder blades, and head against a wall, feet a few inches out from the wall.','Keeping the back of your head on the wall, gently glide your chin straight back, flattening the curve of your neck against the wall.','Keep your shoulders down and relaxed rather than shrugged.']::text[], ARRAY['Common mistake: tipping the chin down toward the chest instead of gliding straight back.']::text[], 'neck', '{}'::text[], 'wall', 'face-neck', 'beginner', ARRAY['rehabilitation']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-chin-tuck-standing-wall', ARRAY['wall']::text[], 'beginner', ARRAY['Stand with your back, shoulder blades, and head against a wall, feet a few inches out from the wall.','Keeping the back of your head on the wall, gently glide your chin straight back, flattening the curve of your neck against the wall.','Keep your shoulders down and relaxed rather than shrugged.','Breathe steadily as you hold the glided-back position.','Common mistake: tipping the chin down toward the chest instead of gliding straight back.','Hold each rep 5 seconds, 8-10 reps.']::text[], ARRAY['stability']::text[], '{}'::text[], ARRAY['deep neck flexors']::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-deep-neck-flexor-hold-progression', 'Deep Neck Flexor Hold – Progression', 'mef-custom-deep-neck-flexor-hold-progression', 'A harder progression from the two chin tucks. A small head lift held under a locked-in chin tuck.', ARRAY['Lie on your back, knees bent, and perform a gentle chin tuck as in the supine version.','From the tucked position, lift only your head a small amount off the floor. An inch or two, not a full crunch. Keeping the chin tuck locked in.','Keep your neck long and jaw soft; the lift should come from the deep front-of-neck muscles, not the jaw or big neck muscles straining forward.']::text[], ARRAY['Common mistake: letting the chin poke forward as the head lifts. If that happens, lower the head slightly until the tuck holds.']::text[], 'neck', '{}'::text[], 'bodyweight', 'face-neck', 'intermediate', ARRAY['rehabilitation']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-deep-neck-flexor-hold-progression', ARRAY['bodyweight']::text[], 'intermediate', ARRAY['Lie on your back, knees bent, and perform a gentle chin tuck as in the supine version.','From the tucked position, lift only your head a small amount off the floor. An inch or two, not a full crunch. Keeping the chin tuck locked in.','Keep your neck long and jaw soft; the lift should come from the deep front-of-neck muscles, not the jaw or big neck muscles straining forward.','Breathe steadily throughout the hold rather than holding your breath.','Common mistake: letting the chin poke forward as the head lifts. If that happens, lower the head slightly until the tuck holds.','Hold 5-10 seconds, 5-6 reps. Progress from the supine and standing chin tucks before adding this one.']::text[], ARRAY['stability']::text[], '{}'::text[], ARRAY['deep neck flexors']::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-prone-y-raise', 'Prone Y Raise', 'mef-custom-prone-y-raise', 'Prone strengthening for the lower traps and thoracic extensors in a Y arm position.', ARRAY['Lie face-down, arms extended overhead in a wide ''Y'' shape, thumbs pointing up.','Lift your arms and chest slightly off the floor, leading with your thumbs, squeezing the lower part of your shoulder blades together and down.','Keep your neck long, looking at the floor, rather than craning up to look forward.']::text[], ARRAY['Common mistake: shrugging the shoulders up toward the ears instead of drawing the shoulder blades down and in.']::text[], 'lower_traps', ARRAY['middle_traps']::text[], 'bodyweight', 'back', 'beginner', ARRAY['strength','rehabilitation']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-prone-y-raise', ARRAY['bodyweight']::text[], 'beginner', ARRAY['Lie face-down, arms extended overhead in a wide ''Y'' shape, thumbs pointing up.','Lift your arms and chest slightly off the floor, leading with your thumbs, squeezing the lower part of your shoulder blades together and down.','Keep your neck long, looking at the floor, rather than craning up to look forward.','Breathe out as you lift, breathe in as you lower with control.','Common mistake: shrugging the shoulders up toward the ears instead of drawing the shoulder blades down and in.','8-10 slow reps, hold each 2 seconds at the top.']::text[], ARRAY['strength']::text[], '{}'::text[], ARRAY['lower traps','mid traps','thoracic extensors']::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-prone-t-raise', 'Prone T Raise', 'mef-custom-prone-t-raise', 'Prone strengthening for the mid traps and rhomboids in a T arm position.', ARRAY['Lie face-down, arms out to the sides at shoulder height in a ''T'' shape, palms facing down.','Lift your arms and chest slightly off the floor, squeezing your shoulder blades together toward your spine.','Keep your neck long and your gaze down at the floor throughout.']::text[], ARRAY['Common mistake: using momentum to jerk the arms up. Keep the movement slow enough to feel the muscles between the shoulder blades working.']::text[], 'middle_traps', ARRAY['rhomboids']::text[], 'bodyweight', 'back', 'beginner', ARRAY['strength','rehabilitation']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-prone-t-raise', ARRAY['bodyweight']::text[], 'beginner', ARRAY['Lie face-down, arms out to the sides at shoulder height in a ''T'' shape, palms facing down.','Lift your arms and chest slightly off the floor, squeezing your shoulder blades together toward your spine.','Keep your neck long and your gaze down at the floor throughout.','Breathe out as you lift, breathe in as you lower with control.','Common mistake: using momentum to jerk the arms up. Keep the movement slow enough to feel the muscles between the shoulder blades working.','8-10 slow reps, hold each 2 seconds at the top.']::text[], ARRAY['strength']::text[], '{}'::text[], ARRAY['mid traps','rhomboids','thoracic extensors']::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-wall-angels', 'Wall Angels', 'mef-custom-wall-angels', 'Standing wall drill combining thoracic extension with lower trap/serratus strengthening.', ARRAY['Stand with your head, upper back, and glutes against a wall, feet a few inches out, low back gently flattened.','Raise your arms to a goalpost position against the wall, elbows and wrists touching if possible.','Slowly slide your arms up overhead and back down, keeping as much contact with the wall as you can.']::text[], ARRAY['Common mistake: letting the low back arch off the wall or the arms peel away from it to force a bigger range. A smaller range with full contact beats a bigger range without it.']::text[], 'lower_traps', ARRAY['serratus_anterior','middle_traps']::text[], 'wall', 'back', 'beginner', ARRAY['strength','mobility','rehabilitation']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-wall-angels', ARRAY['wall']::text[], 'beginner', ARRAY['Stand with your head, upper back, and glutes against a wall, feet a few inches out, low back gently flattened.','Raise your arms to a goalpost position against the wall, elbows and wrists touching if possible.','Slowly slide your arms up overhead and back down, keeping as much contact with the wall as you can.','Breathe out as you slide up, in as you lower.','Common mistake: letting the low back arch off the wall or the arms peel away from it to force a bigger range. A smaller range with full contact beats a bigger range without it.','8-10 slow reps.']::text[], ARRAY['strength','stability']::text[], '{}'::text[], ARRAY['lower traps','mid traps','serratus anterior','thoracic extensors']::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-thoracic-extension-over-foam-roller', 'Thoracic Extension Over Foam Roller', 'mef-custom-thoracic-extension-over-foam-roller', 'Active thoracic extension mobility drill over a foam roller.', ARRAY['Lie on your back with the roller placed horizontally under your shoulder blades, knees bent, hands cradling behind your head.','Gently arch your upper back over the roller, letting your head and shoulders drape back toward the floor.','Keep your hips down and core lightly braced. The extension should come from the upper back, not the low back.']::text[], ARRAY['Common mistake: extending from the low back by lifting the hips. Keep them grounded throughout.']::text[], 'back', ARRAY['upper_back']::text[], 'foam roller', 'mobility', 'beginner', ARRAY['mobility']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-thoracic-extension-over-foam-roller', ARRAY['foam roller']::text[], 'beginner', ARRAY['Lie on your back with the roller placed horizontally under your shoulder blades, knees bent, hands cradling behind your head.','Gently arch your upper back over the roller, letting your head and shoulders drape back toward the floor.','Keep your hips down and core lightly braced. The extension should come from the upper back, not the low back.','Breathe fully into your chest as you extend, then curl back up to the starting position.','Common mistake: extending from the low back by lifting the hips. Keep them grounded throughout.','8-10 slow reps.']::text[], ARRAY['mobility']::text[], ARRAY['upper back']::text[], '{}'::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-4-point-tva-vacuum', '4-Point TVA Vacuum', 'mef-custom-4-point-tva-vacuum', 'Deep core (TVA) activation drill on hands and knees.', ARRAY['Start on hands and knees, spine in a neutral, flat position. Not arched, not rounded.','Exhale fully, then draw your belly button up and in toward your spine without moving your back or hips.','Hold the draw-in while breathing shallow and steady into your ribs for a few seconds.']::text[], ARRAY['Common mistake: tucking the pelvis or rounding the low back to fake the draw-in. The spine should stay still throughout.']::text[], 'core', ARRAY['transverse_abdominis']::text[], 'bodyweight', 'core', 'beginner', ARRAY['core','isometric','rehabilitation']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-4-point-tva-vacuum', ARRAY['bodyweight']::text[], 'beginner', ARRAY['Start on hands and knees, spine in a neutral, flat position. Not arched, not rounded.','Exhale fully, then draw your belly button up and in toward your spine without moving your back or hips.','Hold the draw-in while breathing shallow and steady into your ribs for a few seconds.','Release fully between reps rather than staying braced the whole set.','Common mistake: tucking the pelvis or rounding the low back to fake the draw-in. The spine should stay still throughout.','Hold 5-8 seconds, 6-8 reps.']::text[], ARRAY['core_stability']::text[], '{}'::text[], ARRAY['deep abdominals (TVA)']::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym") values ('mef_custom', 'mef-custom-supine-tva-draw-in-breathing', 'Supine TVA Draw-In Breathing', 'mef-custom-supine-tva-draw-in-breathing', 'Deep core (TVA) activation drill lying on the back, coordinated with breathing.', ARRAY['Lie on your back, knees bent, feet flat, low back in a relaxed neutral position.','Inhale into your belly and ribs, letting them expand fully.','As you exhale, gently draw your lower belly in and down toward your spine, without flattening your low back into the floor or tilting your pelvis.']::text[], ARRAY['Common mistake: bearing down or bracing hard like a crunch. This should feel like a slow, gentle hollowing, not a squeeze.']::text[], 'core', ARRAY['transverse_abdominis']::text[], 'bodyweight', 'core', 'beginner', ARRAY['core','isometric','rehabilitation']::text[], false, false, false) on conflict (provider, external_id) do update set "name" = excluded."name", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "updated_at" = now();
insert into mef_exercise_metadata ("provider","external_id","equipment","difficulty","coaching_cues","corrective_roles","muscles_stretched","muscles_strengthened","strain_level","spinal_flexion_core") values ('mef_custom', 'mef-custom-supine-tva-draw-in-breathing', ARRAY['bodyweight']::text[], 'beginner', ARRAY['Lie on your back, knees bent, feet flat, low back in a relaxed neutral position.','Inhale into your belly and ribs, letting them expand fully.','As you exhale, gently draw your lower belly in and down toward your spine, without flattening your low back into the floor or tilting your pelvis.','Keep breathing shallow and steady into your upper ribs while holding the gentle draw-in.','Common mistake: bearing down or bracing hard like a crunch. This should feel like a slow, gentle hollowing, not a squeeze.','Hold 5-8 seconds, 8-10 reps.']::text[], ARRAY['core_stability']::text[], '{}'::text[], ARRAY['deep abdominals (TVA)']::text[], 'low', false) on conflict (provider, external_id) do update set "equipment" = excluded."equipment", "difficulty" = excluded."difficulty", "coaching_cues" = excluded."coaching_cues", "corrective_roles" = excluded."corrective_roles", "muscles_stretched" = excluded."muscles_stretched", "muscles_strengthened" = excluded."muscles_strengthened", "strain_level" = excluded."strain_level", "spinal_flexion_core" = excluded."spinal_flexion_core", "updated_at" = now();
